function transform(message, context) {
  var body = message.payload;

  // The serverless body may arrive as a raw string; normalize to an object.
  if (typeof body === 'string') {
    body = JSON.parse(body.replace(/^\uFEFF/, '').trim());
  }

  var eventType = body && body.eventType;
  var notif = (body && body.payload) ? body.payload : {};

  // Scope the Authorize.net webhook subscription to the capture event. If a
  // different event arrives, fail loudly rather than silently advancing.
  if (eventType !== 'net.authorize.payment.authcapture.created') {
    throw new Error('Ignoring unexpected webhook eventType: ' + eventType + '. Scope the Authorize.net webhook to net.authorize.payment.authcapture.created.');
  }

  var transId = notif.id;
  if (!transId) {
    throw new Error('Webhook payload missing transaction id.');
  }

  // NOTE: X-ANET-Signature (HMAC-SHA512 of the raw body, keyed by signatureKey)
  // can be validated here if the transform runtime exposes an HMAC facility.
  // It is intentionally not enforced because the getTransactionDetails re-fetch
  // below is the authoritative confirmation and cannot be spoofed.

  context.set('transId', String(transId));
  return message;
}

function transform(message, context) {
  var apiUrl = context.environment === 'production'
    ? 'https://api.authorize.net/xml/v1/request.api'
    : 'https://apitest.authorize.net/xml/v1/request.api';
  context.set('apiUrl', apiUrl);

  message.payload = {
    getTransactionDetailsRequest: {
      merchantAuthentication: {
        name: context.authNetLoginId,
        transactionKey: context.authNetTransactionKey
      },
      transId: context.transId
    }
  };
  return message;
}

function transform(message, context) {
  var raw = message.payload;
  if (typeof raw === 'string') {
    raw = JSON.parse(raw.replace(/^\uFEFF/, '').trim());
  }

  var resp = raw.getTransactionDetailsResponse || raw;
  var msgs = resp.messages || {};
  if ((msgs.resultCode || '').toLowerCase() !== 'ok') {
    var m = (msgs.message && msgs.message[0]) || {};
    throw new Error('getTransactionDetails failed: [' + m.code + '] ' + m.text);
  }

  var t = resp.transaction;
  if (!t) {
    throw new Error('getTransactionDetails returned no transaction for ' + context.transId);
  }

  // responseCode 1 = approved. For an authCapture, status is capturedPendingSettlement
  // until the nightly batch settles, then settledSuccessfully.
  var approved = String(t.responseCode) === '1';
  var status = t.transactionStatus;
  var captured = (status === 'capturedPendingSettlement' || status === 'settledSuccessfully');

  if (!approved || !captured) {
    throw new Error('Transaction ' + context.transId + ' not confirmed (responseCode=' + t.responseCode + ', status=' + status + '). Not advancing workflow.');
  }

  var order = t.order || {};
  var billTo = t.billTo || {};
  var customer = t.customer || {};
  var amount = (t.settleAmount != null) ? t.settleAmount : t.authAmount;

  // Shape the payload for the Workflow API trigger. invoiceNumber is the
  // student-ID + term correlation key set when the token was minted.
  message.payload = {
    transId: String(t.transId),
    invoiceNumber: order.invoiceNumber || '',
    orderDescription: order.description || '',
    amount: amount,
    transactionStatus: status,
    submitTimeUTC: t.submitTimeUTC || '',
    customerEmail: customer.email || '',
    customerName: ((billTo.firstName || '') + ' ' + (billTo.lastName || '')).trim()
  };
  return message;
}
